package cache;

import util.DHUtil;

import java.security.Key;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// This is used to store the session key generated by the key agreement . This allows same client to come in again and execute a new key agreement.


public class SessionKeyCache {

 /*   static class SessionKeyCacheHolder
    {
         static SessionKeyCache instance = new SessionKeyCache();
    }



    private SessionKeyCache()
    {

    }
    public static SessionKeyCache getInstance()
    {
        return SessionKeyCacheHolder.instance;
    }*/

    Map<String, DHUtil> cache = new ConcurrentHashMap<>();

    public void put(String sessionId , DHUtil util)
    {
        cache.put(sessionId,util);
    }

    public DHUtil get(String sessionId)
    {
        return cache.get(sessionId);
    }

    @Override
    public String toString() {
        return "SessionKeyCache{" +
                "cache=" + cache +
                '}';
    }
}
